/**
 * VTJ 测试夹具构建器
 *
 * 生成一个临时的、自包含的 mock .vtj 项目目录，供测试使用。
 * 目录结构与 vtj-mcp-server.js 中的路径常量保持一致：
 *
 *   <tmpDir>/
 *     project.json              # 项目配置（pages/blocks/apis/dependencies）
 *     .vtj/
 *       projects/<projectId>.json
 *       files/<pageId>.json     # DSL 文件（nodes/state/methods/__VERSION__）
 *       vue/<pageId>.vue        # Vue SFC（template/script/style）
 *       materials/materials.json
 *       router.js
 *     src/router/index.ts
 *
 * 用法：
 *   import { buildFixture, cleanupFixture } from './fixtures/buildFixture.js';
 *   const fixture = buildFixture();
 *   // ... 测试 ...
 *   cleanupFixture(fixture);
 */

import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

/** 生成唯一 ID，如 page_1720000000000_ab12cd */
function generateId(prefix) {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

/** 递归创建目录 */
function ensureDir(dir) {
  mkdirSync(dir, { recursive: true });
}

/** 写入 JSON 文件 */
function writeJSON(filePath, data) {
  writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
}

/** 写入文本文件 */
function writeText(filePath, content) {
  writeFileSync(filePath, content, 'utf-8');
}

/**
 * 构建 Vue SFC 内容。
 * 必须能被 parseVueSFC / extractMethodsFromScript / extractStateFromScript /
 * extractLifeCyclesFromScript / extractVersionFromScript 解析。
 */
function buildVueContent({ id, name, title, version, className }) {
  return `<!-- ${title} -->
<template>
  <div class="${className}">
    <h1>${title}</h1>
    <button @click="handleClick">Click</button>
  </div>
</template>

<script lang="ts">
// @ts-nocheck
import { defineComponent, reactive } from 'vue';
import { useProvider } from '@vtj/renderer';

export default defineComponent({
  name: '${name}',
  setup(props) {
    const provider = useProvider({ id: '${id}', version: '${version}' });
    const state = reactive({
      loading: false,
      count: 0
    });
    return { state, provider };
  },
  methods: {
    async handleClick() {
      this.state.count++;
    },
    reset() {
      this.state.count = 0;
    }
  },
  mounted() {
    this.handleClick();
  }
});
</script>

<style lang="css" scoped>
.${className} {
  padding: 20px;
  font-family: 'Noto Sans SC', 'PingFang SC', sans-serif;
}
</style>`;
}

/**
 * 构建 DSL JSON 内容。
 * 结构对齐 vtj_create_page_scaffold 生成的 DSL：id/name/__VERSION__/state/methods/lifeCycles/nodes。
 */
function buildDslContent({ id, name, version, className }) {
  return {
    id,
    name,
    __VERSION__: version,
    state: {
      loading: { type: 'JSExpression', value: 'false' },
      count: { type: 'JSExpression', value: '0' }
    },
    methods: {
      handleClick: { type: 'asyncMethod', params: [] },
      reset: { type: 'method', params: [] }
    },
    lifeCycles: {
      mounted: { type: 'method' }
    },
    nodes: [
      {
        id: `${id}_root`,
        name: 'div',
        from: '',
        props: {
          class: { type: 'JSExpression', value: `'${className}'` }
        },
        events: {
          click: { type: 'JSFunction', value: '() => {}' }
        },
        directives: [
          { name: 'v-if', value: 'state.loading' }
        ],
        children: [
          {
            id: `${id}_title`,
            name: 'h1',
            from: '',
            children: name
          }
        ],
        locked: false,
        invisible: false
      }
    ]
  };
}

/**
 * 构建项目配置 JSON。
 * 结构对齐 vtj_get_project_info 读取的字段：name/description/platform/homepage/pages/blocks/apis/dependencies/config/locked。
 */
function buildProjectConfig({ projectId, rawPageId, generatedPageId, blockId, apiId }) {
  return {
    name: 'Fixture Project',
    description: 'Test fixture project generated by buildFixture',
    platform: 'web',
    homepage: '/',
    pages: [
      {
        id: rawPageId,
        name: 'RawPage',
        title: 'Raw Page',
        raw: true,
        icon: 'Document',
        hidden: false,
        needLogin: false
      },
      {
        id: generatedPageId,
        name: 'GeneratedPage',
        title: 'Generated Page',
        raw: false,
        icon: 'Collection',
        hidden: false,
        needLogin: false
      }
    ],
    blocks: [
      {
        id: blockId,
        name: 'CustomBlock',
        title: 'Custom Block',
        category: 'custom',
        fromType: 'Schema'
      }
    ],
    apis: [
      {
        id: apiId,
        name: 'getUserInfo',
        label: '获取用户信息',
        method: 'GET',
        url: '/api/user/info'
      }
    ],
    dependencies: [
      { name: '@vtj/renderer', version: '1.0.0' }
    ],
    config: {},
    locked: false
  };
}

/**
 * 构建物料配置 JSON。
 * 结构对齐 vtj_get_component_detail 读取的字段：name/label/categoryId/childIncludes/props/setters/events/snippet。
 */
function buildMaterialConfig() {
  return {
    'el-button': {
      name: 'el-button',
      label: '按钮',
      categoryId: 'element-plus',
      childIncludes: true,
      props: [
        {
          name: 'type',
          label: '类型',
          setters: [{ name: 'SelectSetter', options: ['primary', 'default', 'danger'] }],
          defaultValue: 'default',
          required: false
        },
        {
          name: 'size',
          label: '尺寸',
          setters: ['SelectSetter'],
          defaultValue: 'default',
          required: false
        }
      ],
      events: {
        click: { type: 'JSFunction', value: '() => {}' }
      },
      snippet: { children: '按钮' }
    },
    'el-input': {
      name: 'el-input',
      label: '输入框',
      categoryId: 'element-plus',
      childIncludes: false,
      props: [
        {
          name: 'placeholder',
          label: '占位符',
          setters: [{ name: 'StringSetter' }],
          defaultValue: '',
          required: false
        },
        {
          name: 'clearable',
          label: '可清空',
          setters: [{ name: 'BoolSetter' }],
          defaultValue: false,
          required: false
        }
      ],
      events: {
        change: { type: 'JSFunction', value: '() => {}' }
      },
      snippet: { children: '输入框' }
    }
  };
}

/** 构建 .vtj/router.js 内容 */
function buildVtjRouterContent() {
  return `// VTJ 路由配置
export default {
  staticRoutes: [
    {
      path: '/',
      name: 'home',
      component: () => import('@/pages/home.vue')
    }
  ]
};
`;
}

/** 构建 src/router/index.ts 内容（含可被 vtj_get_routing_info 正则解析的静态路由） */
function buildSrcRouterContent() {
  return `import { createRouter, createWebHistory } from 'vue-router';

const routes = [
  {
    path: '/',
    name: 'home',
    component: () => import('@/pages/home.vue')
  },
  {
    path: '/about',
    name: 'about',
    component: () => import('@/pages/about.vue')
  }
];

export default createRouter({
  history: createWebHistory(),
  routes
});
`;
}

/**
 * 创建测试夹具。
 * 每次调用都会生成一个全新的临时目录。
 *
 * @param {object} [options] 可选覆盖项
 * @returns {object} fixture 对象
 */
export function buildFixture(options = {}) {
  const root = mkdtempSync(join(tmpdir(), 'vtj-fixture-'));

  const projectId = options.projectId || generateId('proj');
  const rawPageId = options.rawPageId || generateId('page');
  const generatedPageId = options.generatedPageId || generateId('page');
  const blockId = options.blockId || generateId('block');
  const apiId = options.apiId || generateId('api');
  const version = String(Date.now());

  // ── 目录结构 ──────────────────────────────────────────
  const vtjDir = join(root, '.vtj');
  const projectsDir = join(vtjDir, 'projects');
  const filesDir = join(vtjDir, 'files');
  const vueDir = join(vtjDir, 'vue');
  const materialsDir = join(vtjDir, 'materials');
  const srcRouterDir = join(root, 'src', 'router');

  ensureDir(projectsDir);
  ensureDir(filesDir);
  ensureDir(vueDir);
  ensureDir(materialsDir);
  ensureDir(srcRouterDir);

  // ── 项目配置 ──────────────────────────────────────────
  const projectConfig = buildProjectConfig({ projectId, rawPageId, generatedPageId, blockId, apiId });
  writeJSON(join(root, 'project.json'), projectConfig);
  writeJSON(join(projectsDir, `${projectId}.json`), projectConfig);

  // ── 页面 DSL + Vue ────────────────────────────────────
  const pages = [
    { id: rawPageId, name: 'RawPage', title: 'Raw Page', className: 'raw-page' },
    { id: generatedPageId, name: 'GeneratedPage', title: 'Generated Page', className: 'generated-page' }
  ];

  for (const page of pages) {
    writeJSON(join(filesDir, `${page.id}.json`), buildDslContent({ ...page, version }));
    writeText(join(vueDir, `${page.id}.vue`), buildVueContent({ ...page, version }));
  }

  // ── 物料配置 ──────────────────────────────────────────
  writeJSON(join(materialsDir, 'materials.json'), buildMaterialConfig());

  // ── 路由配置 ──────────────────────────────────────────
  writeText(join(vtjDir, 'router.js'), buildVtjRouterContent());
  writeText(join(srcRouterDir, 'index.ts'), buildSrcRouterContent());

  return {
    root,
    projectId,
    pageIds: [rawPageId, generatedPageId],
    rawPageId,
    generatedPageId,
    blockId,
    apiId,
    version,
    paths: {
      projectConfig: join(root, 'project.json'),
      projectConfigInVtj: join(projectsDir, `${projectId}.json`),
      dsl: {
        [rawPageId]: join(filesDir, `${rawPageId}.json`),
        [generatedPageId]: join(filesDir, `${generatedPageId}.json`)
      },
      vue: {
        [rawPageId]: join(vueDir, `${rawPageId}.vue`),
        [generatedPageId]: join(vueDir, `${generatedPageId}.vue`)
      },
      materials: join(materialsDir, 'materials.json'),
      vtjRouter: join(vtjDir, 'router.js'),
      srcRouter: join(srcRouterDir, 'index.ts')
    }
  };
}

/**
 * 递归删除夹具临时目录。
 *
 * @param {object} fixture buildFixture() 的返回值
 * @returns {boolean} 是否成功清理
 */
export function cleanupFixture(fixture) {
  if (!fixture?.root) return false;
  try {
    rmSync(fixture.root, { recursive: true, force: true });
    return true;
  } catch (e) {
    return false;
  }
}